// In-app delivery, notification and stock-request workflows for the static demo.
let notifications=read('notifications',[]),stockRequests=read('stock-requests',[]),notificationFilter='All',stockRequestFilter='All',googleLoader=null;
const bellIcon=()=>`<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>`;
function validateAlternatePhone(value=''){const phone=String(value??'').trim();if(phone&&(!/^[0-9+ ()-]{10,18}$/.test(phone)||phone.replace(/\D/g,'').length<10))throw Error('Enter a valid alternate phone number or leave it blank.');return phone}
function validateShipping(data){const get=k=>String(data[k]??'').trim();const address=get('shippingAddress'),city=get('shippingCity'),state=get('shippingState'),pincode=get('shippingPincode'),landmark=get('shippingLandmark');if(address.length<8||address.length>400||!city||city.length>100||!state||state.length>100||!/^[1-9][0-9]{5}$/.test(pincode))throw Error('Provide a complete shipping address, city, state and valid six-digit PIN code.');return {address,city,state,pincode,landmark:landmark.slice(0,180),country:'India'}}
function shippingSummary(o){const s=o.shipping;return s?`${s.address}, ${s.city}, ${s.state} ${s.pincode}, ${s.country||'India'}`:'Shipping address has not been provided for this earlier request.'}
function shippingFields(){const key=window.POWER_ELECTRONICS_CONFIG?.googleMapsApiKey;return `<section class="shipping-section"><div class="form-section-title"><span class="section-number">2</span><div><h3>Shipping address</h3><p>Where should we send your components?</p></div></div><div class="address-helper"><div><b>Find your address with Google <small>Optional</small></b><span>Select a location, then confirm the delivery details below.</span></div><button type="button" class="btn btn-outline btn-small" data-experience="google-address">Search address</button></div><div id="googleaddresshost"></div><p id="googleaddressstatus" class="subtle" role="status">${key?'Google address search is available. You can also enter the address manually.':'Enter your shipping address below. Address search is optional.'}</p><div class="form-grid"><label class="field full">Building / department / street address<input name="shippingAddress" autocomplete="shipping street-address" minlength="8" maxlength="400" value="${esc(profile.address||'')}" required placeholder="Department, building, street and area"></label>${field('City','shippingCity',profile.city||'','text',true)}${field('State','shippingState',profile.state||'','text',true)}${field('PIN code','shippingPincode',profile.pincode||'','text',true,'[1-9][0-9]{5}')}<label class="field">Landmark <span class="subtle">(optional)</span><input name="shippingLandmark" maxlength="180" placeholder="Near gate 2, opposite…"></label></div><p class="subtle">Delivery within India. Check the building, department and PIN code even when using address search.</p></section>`}
const originalCustomerBulkPage=customerBulkPage;
customerBulkPage=function(){let html=originalCustomerBulkPage();html=html.replace('<div class="form-grid">','<div class="form-section-title"><span class="section-number">1</span><div><h3>Contact & institution</h3><p>Tell us who is coordinating this request.</p></div></div><div class="form-grid">');html=html.replace('<label class="field">Institution type',`<label class="field">Alternate phone <span class="subtle">(optional)</span><input name="alternatePhone" type="tel" maxlength="18" pattern="[0-9+ ()-]{10,18}" placeholder="Additional contact number"></label><label class="field">Institution type`);html=html.replace('<div class="bulk-upload">',`${shippingFields()}<div class="form-section-title"><span class="section-number">3</span><div><h3>Component list</h3><p>Upload and review the items you need.</p></div></div><div class="bulk-upload">`);return html};
function viewerKey(){return user?`${user.role}:${user.email}`:''}
function visibleNotifications(){if(!user)return [];return notifications.filter(n=>n.recipient===(user.role==='admin'?'admin':`customer:${user.email}`)||(user.role==='customer'&&n.recipient==='customers'))}
function notificationRead(n){return (n.readBy||[]).includes(viewerKey())}
function addNotification(recipient,type,title,message,link,entityId=''){notifications.unshift({id:crypto.randomUUID(),recipient,type,title,message,link,entityId,at:stamp(),readBy:[]})}
function updateNotificationHeader(){const b=$('#notificationbutton');if(!b)return;const count=visibleNotifications().filter(n=>!notificationRead(n)).length;b.innerHTML=bellIcon()+`<span class="desktop">Updates</span>${count?`<span class="notification-count">${count>99?'99+':count}</span>`:''}`;b.setAttribute('aria-label',`Notifications${count?', '+count+' unread':''}`)}
const originalUpdateHeader=updateHeader;
updateHeader=function(){originalUpdateHeader();updateNotificationHeader()};
function workspaceTransaction(action){const before={bulkDraft:structuredClone(bulkDraft),products:structuredClone(products),cart:structuredClone(cart),bulkOrders:structuredClone(bulkOrders),priceHistory:structuredClone(priceHistory),importDrafts:structuredClone(importDrafts),notifications:structuredClone(notifications),stockRequests:structuredClone(stockRequests)};const keys=['products','cart','bulk-orders','price-history','import-drafts','notifications','stock-requests'];const stored=Object.fromEntries(keys.map(k=>[k,localStorage.getItem('circuit-demo-'+k)]));try{const result=action();persistRecords({products,cart,'bulk-orders':bulkOrders,'price-history':priceHistory,'import-drafts':importDrafts,notifications,'stock-requests':stockRequests});updateHeader();return result}catch(error){bulkDraft=before.bulkDraft;products=before.products;cart=before.cart;bulkOrders=before.bulkOrders;priceHistory=before.priceHistory;importDrafts=before.importDrafts;notifications=before.notifications;stockRequests=before.stockRequests;for(const [k,v] of Object.entries(stored))try{if(v===null)localStorage.removeItem('circuit-demo-'+k);else localStorage.setItem('circuit-demo-'+k,v)}catch{}updateHeader();throw error}}
const previousSubmitBulkRequest=submitBulkRequest;
submitBulkRequest=function(data){return workspaceTransaction(()=>{const o=previousSubmitBulkRequest(data);addNotification('admin','bulk-new','New bulk quotation request',`${o.name} from ${o.institution} requested ${o.items.length} items (${o.items.reduce((a,i)=>a+i.count,0)} units).`,'/admin/bulk-orders',o.id);addNotification(`customer:${o.owner}`,'bulk-submitted','Your bulk request is submitted',`${o.id} is awaiting review. We’ll notify you when its status changes.`,'/bulk-orders',o.id);return o})};
const previousUpdateBulkOrder=updateBulkOrder;
updateBulkOrder=function(id,data){requireDemoAdmin();return workspaceTransaction(()=>{const before=structuredClone(bulkOrders.find(o=>o.id===id));if(!before)throw Error('Request not found.');if(data.status==='Delivered'&&!before.shipping)throw Error('A shipping address is required before marking this request delivered. Contact the customer to provide it.');previousUpdateBulkOrder(id,data);const o=bulkOrders.find(o=>o.id===id);const reference=String(data.deliveryReference??o.deliveryReference??'').trim().slice(0,180);if(before.status==='Completed'&&(before.deliveryReference||'')!==reference)throw Error('Completed requests are closed.');if((before.deliveryReference||'')!==reference)o.history.push({status:o.status,at:stamp(),actor:user.email,note:'Delivery reference: '+(reference||'Removed')});o.deliveryReference=reference;if(before.status!==o.status||before.quote!==o.quote||before.adminNotes!==o.adminNotes||(before.deliveryReference||'')!==reference){addNotification(`customer:${o.owner}`,'bulk-status',before.status!==o.status?`Bulk request ${o.status.toLowerCase()}`:'Your quotation request was updated',`${o.id} · ${o.status}${o.quote===null?'':` · Quote ${money(o.quote)}`}${o.adminNotes?' · '+o.adminNotes:''}`,'/bulk-orders',id)}})};
function notifyCatalogChanges(before){const changes=products.filter(p=>before.find(b=>b.id===p.id)?.price!==p.price&&before.some(b=>b.id===p.id));if(changes.length)addNotification('customers','price-update','Product prices have been updated',changes.length===1?`${changes[0].name}: ${money(before.find(p=>p.id===changes[0].id).price)} → ${money(changes[0].price)}. Review the current price before ordering.`:`Prices for ${changes.length} products have changed. Updated prices are shown on product cards and in your cart.`,'/shop');for(const r of stockRequests.filter(r=>!['Available','Closed'].includes(r.status))){const p=product(r.productId),old=before.find(b=>b.id===r.productId);if(p?.stock>0&&p.active!==false&&(old?.stock===0||old?.active===false)){r.status='Available';r.adminNotes='This product is back in stock. Check current availability before ordering.';r.history.push({status:r.status,at:stamp(),note:r.adminNotes});addNotification(`customer:${r.owner}`,'stock-available','Your requested product is back in stock',`${r.productName} is available again. Current price: ${money(p.price)}.`,'/stock-requests',r.id)}}}
const previousCommitProductChanges=commitProductChanges;
commitProductChanges=function(changes,reason){requireDemoAdmin();return workspaceTransaction(()=>{const before=structuredClone(products);previousCommitProductChanges(changes,reason);notifyCatalogChanges(before)})};
const previousPublishImportProducts=publishImportProducts;
publishImportProducts=function(ids){requireDemoAdmin();return workspaceTransaction(()=>{const before=structuredClone(products),result=previousPublishImportProducts(ids);notifyCatalogChanges(before);return result})};
function markNotificationsRead(ids){if(!user)throw Error('Sign in to view your notifications.');const allowed=new Set(visibleNotifications().map(n=>n.id)),next=structuredClone(notifications);for(const n of next)if(ids.includes(n.id)&&allowed.has(n.id)&&!(n.readBy||[]).includes(viewerKey()))n.readBy=[...(n.readBy||[]),viewerKey()];persistRecords({notifications:next});notifications=next;updateNotificationHeader()}
function notificationsPage(){if(!user)return `<div class="wrap">${crumbs('Notifications')}<div class="success">${bellIcon()}<h2>Your updates, in one place.</h2><p>Sign in to see quotation updates, price changes and stock availability.</p><button class="btn" data-action="login">Customer login</button><button class="btn btn-outline" data-action="admin-login">Admin login</button></div></div>`;const visible=visibleNotifications(),list=visible.filter(n=>notificationFilter!=='Unread'||!notificationRead(n)),unread=visible.filter(n=>!notificationRead(n)).length;const content=`${opsHeading(user.role==='admin'?'Store activity':'Your activity','Notifications','Stay up to date with requests, quotations and your next build.')}<section class="panel notification-panel"><div class="section-head"><div class="notification-tabs">${['All','Unread'].map(t=>`<button class="${notificationFilter===t?'active':''}" data-experience="notification-filter" data-filter="${t}">${t}${t==='Unread'?` (${unread})`:''}</button>`).join('')}</div><button class="btn btn-outline btn-small" data-experience="read-all" ${!unread?'disabled':''}>Mark all as read</button></div>${list.length?`<div class="notification-list">${list.map(n=>`<article class="notification-item ${notificationRead(n)?'':'unread'}"><span class="notification-symbol">${n.type.startsWith('bulk')?icon('box'):n.type==='price-update'?icon('cart'):icon('support')}</span><div><div class="notification-title"><b>${esc(n.title)}</b>${notificationRead(n)?'':'<span class="unread-dot" aria-label="Unread"></span>'}</div><p>${esc(n.message)}</p><small>${dateLabel(n.at)}</small><button class="text-link" data-experience="notification-open" data-id="${n.id}">View details →</button></div></article>`).join('')}</div>`:'<div class="import-empty"><h3>You’re all caught up.</h3><p>New updates will appear here.</p></div>'}</section><p class="subtle notification-footnote">In-app notifications for this browser demo. Email, SMS and push delivery are not connected.</p>`;return user.role==='admin'?importLayout(content,'notifications'):`<div class="wrap experience-page">${crumbs('Notifications')}${content}</div>`}
function priceUpdatedNotice(id){const p=product(id),h=priceHistory.find(h=>h.productId===Number(id));if(!p||!h||h.after!==p.price)return '';return `<div class="customer-price-update"><span>${icon('box',13)} Price updated</span><small>${new Date(h.at).toLocaleDateString('en-IN',{day:'numeric',month:'short'})} · Previously ${money(h.before)}</small></div>`}
function pendingStockRequest(id){return user?.role==='customer'?stockRequests.find(r=>r.owner===user.email&&r.productId===Number(id)&&!['Available','Closed'].includes(r.status)):null}
function stockRequestCTA(p){if(p.stock||user?.role==='admin')return '';const existing=pendingStockRequest(p.id);return `<button class="stock-request-cta ${existing?'requested':''}" data-experience="request-stock" data-id="${p.id}" ${existing?'disabled':''}>${icon('support',15)} ${existing?'Stock request sent':'Request availability'}</button>`}
function requestStockDialog(id){const p=product(id);if(!p||p.active===false||p.stock)throw Error('This product is unavailable for stock requests.');if(user?.role!=='customer'){login('customer');toast('Sign in as a customer to request stock.');return}if(pendingStockRequest(id))throw Error('You already have an open request for this product.');showModal(`<div class="eyebrow">Out of stock</div><h2>Need this component?</h2><p>Send your requirement to our team. You’ll receive an in-app update when availability changes.</p><div class="request-product"><img src="${img(p.id)}" alt=""><div><b>${esc(p.name)}</b><small>Current listed price: ${money(p.price)}</small></div></div><form id="stockrequestform" data-id="${p.id}"><div class="form-grid">${field('Full name','name',profile.name,'text',true)}${field('Email','email',user.email,'email',true)}${field('Phone number','phone',profile.phone,'tel',true,'[0-9+ ()-]{10,18}')}<label class="field">Required units<input type="number" name="count" min="1" max="100000" step="1" value="1" required></label><label class="field full">Requirements <span class="subtle">(optional)</span><textarea name="notes" maxlength="1000" rows="3" placeholder="Project, institution, preferred date…"></textarea></label></div><p class="error" role="alert"></p><button class="btn">Send stock request</button></form>`)}
function submitStockRequest(id,data){if(user?.role!=='customer')throw Error('Sign in as a customer first.');const p=product(id),count=Number(data.count);if(!p||p.active===false||p.stock>0)throw Error('This product is unavailable or already in stock. Refresh and add it to your cart.');if(pendingStockRequest(id))throw Error('You already have an open request for this product.');if(!String(data.name||'').trim()||!/^\S+@\S+\.\S+$/.test(data.email||'')||!validateAlternatePhone(data.phone)||!Number.isInteger(count)||count<1||count>100000)throw Error('Provide valid contact details and a positive whole-number quantity.');return workspaceTransaction(()=>{const r={id:'SR-'+crypto.randomUUID().slice(0,8).toUpperCase(),owner:user.email,productId:p.id,productName:p.name,name:String(data.name).trim().slice(0,180),email:String(data.email).trim().toLowerCase(),phone:String(data.phone).trim(),count,notes:String(data.notes||'').trim().slice(0,1000),status:'Requested',createdAt:stamp(),adminNotes:'',history:[{status:'Requested',at:stamp(),note:'Availability requested'}]};stockRequests.unshift(r);addNotification('admin','stock-new','New out-of-stock request',`${r.name} needs ${count} units of ${r.productName}.`,'/admin/stock-requests',r.id);addNotification(`customer:${r.owner}`,'stock-submitted','Stock request received',`We’ll review your request for ${r.productName} (${count} units).`,'/stock-requests',r.id);return r})}
function stockRequestsPage(){if(!user)return `<div class="wrap">${crumbs('Stock requests')}<div class="success"><h2>Track the parts you need.</h2><p>Sign in to send and track availability requests.</p><button class="btn" data-action="login">Customer login</button></div></div>`;const isAdmin=user.role==='admin',mine=stockRequests.filter(r=>isAdmin||r.owner===user.email),list=mine.filter(r=>stockRequestFilter==='All'||r.status===stockRequestFilter);const content=`${opsHeading(isAdmin?'Inventory demand':'Your component requests',isAdmin?'Stock requests':'Requested availability',isAdmin?'Review customer demand and notify customers when components return.':'Follow the availability of the components you requested.')}<section class="panel"><div class="section-head"><h3>${mine.length} requests</h3><select data-experience-filter="requests" aria-label="Filter stock request status">${['All','Requested','Reviewing','Available','Closed'].map(s=>`<option ${stockRequestFilter===s?'selected':''}>${s}</option>`).join('')}</select></div>${list.length?`<div class="stock-request-list">${list.map(r=>`<article class="stock-request-row"><img src="${img(r.productId)}" alt=""><div><small>${esc(r.id)} · ${dateLabel(r.createdAt)}</small><h3>${esc(r.productName)}</h3><p>${r.count} units requested${isAdmin?' · '+esc(r.name):''}</p>${r.adminNotes?`<p class="admin-response">${esc(r.adminNotes)}</p>`:''}</div><div class="stock-row-actions"><span class="workflow-pill request-${r.status.toLowerCase()}">${esc(r.status)}</span><button class="btn btn-outline btn-small" data-experience="stock-detail" data-id="${r.id}">${isAdmin?'Review request':'View details'}</button>${!isAdmin&&product(r.productId)?.stock?`<a class="text-link" href="#/product/${r.productId}">View available product →</a>`:''}</div></article>`).join('')}</div>`:'<div class="import-empty"><h3>No requests here yet.</h3><p>Requests raised from an out-of-stock product will appear here.</p><a class="btn btn-outline" href="#/shop">Browse components</a></div>'}</section>`;return isAdmin?importLayout(content,'requests'):`<div class="wrap experience-page">${crumbs('Stock requests')}${content}</div>`}
function stockDetail(id){const r=stockRequests.find(r=>r.id===id);if(!r||!user||(user.role!=='admin'&&r.owner!==user.email))throw Error('Request unavailable.');const isAdmin=user.role==='admin';showModal(`<div class="eyebrow">Stock request ${esc(r.id)}</div><h2>${esc(r.productName)}</h2><p>${r.count} units · ${esc(r.status)}</p><div class="request-contact"><b>${esc(r.name)}</b><span>${esc(r.email)} · ${esc(r.phone)}</span>${r.notes?`<span>${esc(r.notes)}</span>`:''}</div>${isAdmin?`<form id="stockmanageform" data-id="${r.id}"><div class="form-grid"><label class="field">Status<select name="status">${['Requested','Reviewing','Available','Closed'].map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Current inventory<input readonly value="${product(r.productId)?.stock||0} units"></label><label class="field full">Customer-visible update<textarea name="adminNotes" maxlength="1000" rows="3">${esc(r.adminNotes)}</textarea></label></div><p class="error" role="alert"></p><button class="btn">Save & notify customer</button><a class="text-link" href="#/admin/pricing" data-experience="close-link">Update inventory</a></form>`:`<div class="saved-note">${esc(r.adminNotes||'We are reviewing your requirement. Updates will appear in your notifications.')}</div>`}<h3 class="timeline-title">Request activity</h3><div class="activity-timeline">${r.history.slice().reverse().map(h=>`<div><b>${esc(h.status)}</b><small>${dateLabel(h.at)}</small><p>${esc(h.note)}</p></div>`).join('')}</div>`)}
function updateStockRequest(id,data){requireDemoAdmin();return workspaceTransaction(()=>{const r=stockRequests.find(r=>r.id===id);if(!r)throw Error('Request not found.');if(!['Requested','Reviewing','Available','Closed'].includes(data.status))throw Error('Choose a valid status.');if(r.status==='Closed')throw Error('This request is already closed.');if(data.status==='Available'&&!product(r.productId)?.stock)throw Error('Restock the product before marking it available.');const notes=String(data.adminNotes||'').trim().slice(0,1000);if(r.status===data.status&&r.adminNotes===notes)return;r.status=data.status;r.adminNotes=notes;r.history.push({status:r.status,at:stamp(),note:notes||'Request status updated'});addNotification(`customer:${r.owner}`,'stock-status',`Stock request ${r.status.toLowerCase()}`,`${r.productName}${notes?' · '+notes:''}`,'/stock-requests',id)})}
bulkDetail=function(id){const o=bulkOrders.find(o=>o.id===id);if(!o||!user||(user.role!=='admin'&&o.owner!==user.email))throw Error('Request is unavailable for this account.');const isAdmin=user.role==='admin',next=bulkStages[bulkStages.indexOf(o.status)+1],closed=o.status==='Completed';showModal(`<div class="bulk-detail-header"><div><div class="eyebrow">Institutional quotation</div><h2>${esc(o.id)}</h2><p>${esc(o.institutionType)} · ${esc(o.institution)}</p></div>${stagePill(o.status)}</div>${bulkTimeline(o)}<div class="bulk-detail-grid"><section class="detail-info-card"><h3>${icon('user',17)} Contact details</h3><b>${esc(o.name)}</b><span>${esc(o.email)}</span><span>Primary: ${esc(o.phone)}</span><span>Alternate: ${esc(o.alternatePhone||'Not provided')}</span></section><section class="detail-info-card"><h3>${icon('truck',17)} Ship to</h3><p>${esc(shippingSummary(o))}</p>${o.shipping?.landmark?`<small>Landmark: ${esc(o.shipping.landmark)}</small>`:''}${o.shipping?`<a class="text-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(shippingSummary(o))}" target="_blank" rel="noopener noreferrer">View on Google Maps ↗</a>`:''}</section></div><div class="bulk-detail-summary"><span><small>Requested quantities</small><b>${o.items.reduce((a,i)=>a+i.count,0)} units / ${o.items.length} items</b></span><span><small>Quotation</small><b>${o.quote===null?'Pending':money(o.quote)}</b></span><span><small>Submitted</small><b>${dateLabel(o.createdAt)}</b></span></div>${o.notes?`<div class="customer-requirements"><b>Customer requirements</b><p>${esc(o.notes)}</p></div>`:''}<div class="section-head"><h3>Requested components</h3><small>${esc(o.filename)}</small></div><div class="table-scroll bulk-preview-table"><table class="data-table"><thead><tr><th>Item</th><th>Count</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(i.item)}</td><td>${i.count}</td></tr>`).join('')}</tbody></table></div>${isAdmin&&!closed?`<section class="status-update-panel"><h3>Update quotation & status</h3><p>${next?`Next stage: ${next}. Saving a change sends an in-app update to the customer.`:'Request completed.'}</p><form id="bulkmanageform" data-id="${o.id}"><div class="form-grid"><label class="field">Quote total (₹)<input name="quote" type="number" min="0.01" max="1000000000" step="0.01" value="${o.quote??''}"></label><label class="field">Status<select name="status"><option>${o.status}</option>${next?`<option>${next}</option>`:''}</select></label><label class="field full">Delivery / tracking reference <span class="subtle">(optional)</span><input name="deliveryReference" value="${esc(o.deliveryReference||'')}" maxlength="180" placeholder="Courier or dispatch reference"></label><label class="field full">Customer-visible notes<textarea name="adminNotes" maxlength="2000" rows="3" placeholder="Quotation details, delivery update or next steps…">${esc(o.adminNotes)}</textarea></label></div><p id="bulkmanageerror" class="error" role="alert"></p><button class="btn">Save update & notify customer</button></form></section>`:`<div class="saved-note">${closed?'Request completed. ':''}${o.adminNotes?esc(o.adminNotes):'Our team will notify you when this request progresses.'}${o.deliveryReference?`<p>Delivery reference: ${esc(o.deliveryReference)}</p>`:''}</div>`}<h3 class="timeline-title">Activity timeline</h3><div class="activity-timeline">${o.history.slice().reverse().map(h=>`<div><b>${esc(h.status)}</b><small>${dateLabel(h.at)}</small><p>${esc(h.note)}</p></div>`).join('')}</div>`);$('#modal').classList.add('operations-modal','bulk-detail-modal')};
function addressFromComponents(components){const get=type=>components.find(c=>c.types?.includes(type))?.longText||'';return {address:[get('premise'),get('street_number'),get('route'),get('sublocality_level_1')].filter(Boolean).join(', '),city:get('locality')||get('postal_town')||get('administrative_area_level_2'),state:get('administrative_area_level_1'),pincode:get('postal_code')}}
async function enableGoogleAddress(){const key=window.POWER_ELECTRONICS_CONFIG?.googleMapsApiKey,status=$('#googleaddressstatus'),host=$('#googleaddresshost');if(!status||!host)return;if(!key){status.textContent='Address search is unavailable right now. Please enter your shipping address in the fields below.';return}if(host.childElementCount)return;status.textContent='Loading Google address search…';try{if(!googleLoader)googleLoader=new Promise((resolve,reject)=>{if(window.google?.maps?.importLibrary){resolve();return}const script=document.createElement('script'),timer=setTimeout(()=>{googleLoader=null;reject(Error('Address search timed out.'))},15000);window.powerElectronicsMapsReady=()=>{clearTimeout(timer);resolve()};script.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(key)}&libraries=places&v=weekly&loading=async&callback=powerElectronicsMapsReady`;script.async=true;script.onerror=()=>{clearTimeout(timer);googleLoader=null;reject(Error('Address search could not be loaded.'))};document.head.appendChild(script)});await googleLoader;const {PlaceAutocompleteElement}=await window.google.maps.importLibrary('places');if(!host.isConnected)return;const widget=new PlaceAutocompleteElement({includedRegionCodes:['in']});widget.setAttribute('aria-label','Search shipping address with Google');host.appendChild(widget);widget.addEventListener('gmp-select',async({placePrediction})=>{try{const place=placePrediction.toPlace();await place.fetchFields({fields:['addressComponents','formattedAddress']});if(!host.isConnected)return;const address=addressFromComponents(place.addressComponents||[]);const form=$('#bulkrequestform');for(const [key,value] of Object.entries(address)){const input=form?.querySelector(`[name="shipping${key[0].toUpperCase()+key.slice(1)}"]`);if(input)input.value=value}if(!address.address&&place.formattedAddress)form.querySelector('[name="shippingAddress"]').value=place.formattedAddress;status.textContent='Address selected. Confirm your building, department, city and PIN code before submitting.'}catch{status.textContent='Could not fetch this address. Please enter the details manually.'}});widget.addEventListener('gmp-error',()=>{status.textContent='Google search is unavailable. Enter your shipping address manually.'});status.textContent='Search for your location, then confirm the delivery details below.'}catch(error){status.textContent=error.message+' You can enter your address manually.'}}
const previousRender=render;
render=function(){previousRender();if(!route().path.startsWith('/admin')&&['/cart','/checkout'].includes(route().path)){const changed=cart.map(i=>priceHistory.find(h=>h.productId===i.id&&product(i.id)?.price===h.after)).filter(Boolean);if(changed.length)$('#app').insertAdjacentHTML('afterbegin',`<div class="wrap"><div class="cart-price-alert">${icon('box',19)}<div><b>Some product prices have changed</b><p>${changed.length} cart item${changed.length===1?'':'s'} now use the updated catalog price. Review your total before ordering.</p></div><a href="#/notifications">View updates</a></div></div>`)}updateNotificationHeader()};
document.addEventListener('click',e=>{const b=e.target.closest('[data-experience]');if(!b)return;const action=b.dataset.experience;try{if(action==='google-address'){void enableGoogleAddress();return}if(action==='request-stock'){requestStockDialog(Number(b.dataset.id));return}if(action==='notification-filter'){notificationFilter=b.dataset.filter;render()}else if(action==='read-all'){markNotificationsRead(visibleNotifications().map(n=>n.id));render()}else if(action==='notification-open'){const n=visibleNotifications().find(n=>n.id===b.dataset.id);if(!n)throw Error('Notification unavailable.');markNotificationsRead([n.id]);navigate(n.link);if(n.entityId){if(n.type.startsWith('bulk'))bulkDetail(n.entityId);else if(n.type.startsWith('stock'))stockDetail(n.entityId)}}else if(action==='stock-detail')stockDetail(b.dataset.id);else if(action==='close-link')closeModal();else if(action==='single-out'){requireDemoAdmin();const p=product(b.dataset.id);if(!p)throw Error('Product not found.');showModal(`<div class="eyebrow">Inventory control</div><h2>Mark this product out of stock?</h2><p>${esc(p.name)} will display “Out of stock”. Customers can send an availability request.</p><button class="btn" data-experience="confirm-single-out" data-id="${p.id}">Confirm out of stock</button>`)}else if(action==='confirm-single-out'){commitProductChanges([{id:Number(b.dataset.id),stock:0}],'Marked out of stock');closeModal();render();toast('Product marked out of stock')}}catch(error){toast(error.message)}});
document.addEventListener('change',e=>{if(e.target.dataset.experienceFilter==='requests'){stockRequestFilter=e.target.value;render()}});
document.addEventListener('submit',e=>{const f=e.target;if(!['stockrequestform','stockmanageform'].includes(f.id))return;e.preventDefault();try{const data=Object.fromEntries(new FormData(f));if(f.id==='stockrequestform'){submitStockRequest(f.dataset.id,data);closeModal();render();toast('Stock request sent to the admin')}else{updateStockRequest(f.dataset.id,data);closeModal();render();toast('Request updated and customer notified')}}catch(error){f.querySelector('[role="alert"]').textContent=error.message}});
$('#modal').addEventListener('close',()=>$('#modal').classList.remove('bulk-detail-modal'));
window.addEventListener('storage',e=>{if(!e.key?.startsWith('circuit-demo-'))return;products=read('products',products);cart=read('cart',cart);bulkOrders=read('bulk-orders',bulkOrders);priceHistory=read('price-history',priceHistory);notifications=read('notifications',notifications);stockRequests=read('stock-requests',stockRequests);updateHeader();if(!$('#modal').open&&!document.activeElement?.closest?.('form'))render()});
// Initial rendering happens after admin-features.js loads.
